LEARNING_JS += r"""
const EXPERIMENT_UI={epoch:0,view:null,requests:new Map()};
const experimentStates={draft:'草稿，尚未封存',sealed:'已封存，尚未执行',running:'正在执行',cancelling:'正在停止',mechanism_passed:'合成机制通过',not_passed:'合成机制未通过',cancelled:'已取消',timed_out:'已超时',stale:'来源已变化',unknown:'结果未知',planned:'已计划',reserved:'已预留预算',intent:'已登记派发意图',completed:'已完成',failed:'执行失败',not_executed:'未执行'};
function experimentContext(c){const a=S.meta?.access;return JSON.stringify([typeof ACCESS==='undefined'?'':ACCESS.base,a?.tenant?.id??'',a?.user??S.meta?.user??'',a?.context_token??'',c.key])}
function learningExperimentsClear(){EXPERIMENT_UI.epoch++;const view=EXPERIMENT_UI.view;EXPERIMENT_UI.view=null;EXPERIMENT_UI.requests.clear();if(view?.box?.isConnected)view.box.innerHTML='<p class="learning-muted">身份或权限已变化，请重新读取演练。</p>'}
function experimentCurrent(v){return EXPERIMENT_UI.view===v&&v.epoch===EXPERIMENT_UI.epoch&&learningCurrent(v.c)&&v.box.isConnected&&v.context===experimentContext(v.c)&&(typeof ACCESS==='undefined'||!ACCESS.blocked&&(!ACCESS.base||ACCESS.ready))}
function experimentStorageKey(identity){return 'webuddy.experiment.pending.v2:'+encodeURIComponent(identity)}
// Receipt recovery is not a page cache: accessLock must not erase an unknown
// write. Native storage uses its own tenant/person/account-epoch/project key.
function experimentStorage(){return typeof ACCESS_RAW_SESSION==='undefined'?globalThis.sessionStorage:ACCESS_RAW_SESSION}
function experimentSave(v){try{if(!v.identity)throw Error('unbound personal identity');const records=Array.from(EXPERIMENT_UI.requests.entries()).filter(([key,r])=>r.identity===v.identity&&r.state!=='not_written').map(([key,r])=>({key,identity:r.identity,body:r.body,state:r.state==='recorded'?'recorded':'unknown',...(r.state==='recorded'?{receipt:r.receipt}:{})}));experimentStorage().setItem(experimentStorageKey(v.identity),JSON.stringify({schema:1,identity:v.identity,records}));v.storageError='';return true}catch(error){v.storageError='无法保存原请求；为防止重复登记，本次操作暂停。';return false}}
function experimentReadable(v,e,id=null){const p=(S.projects||[]).find(p=>p.key===v.c.key),t=S.meta?.access?.tenant?.id;return !!e&&(!id||e.id===id)&&p?.id===e.project_id&&(!t||String(e.tenant_id)===String(t))&&e.rsi_qualified===false&&e.production_prompt_equivalence===false}
function experimentView(c){const old=EXPERIMENT_UI.view;if(old&&old.c===c&&experimentCurrent(old))return old;const view={c,box:c.root.querySelector('#learningExperiments'),context:experimentContext(c),identity:'',epoch:++EXPERIMENT_UI.epoch,sequence:0,data:null,selected:null,storageError:''};EXPERIMENT_UI.view=view;return view}
function experimentBindIdentity(v,data){
 const r=data.request_identity,a=S.meta?.access;let identity='';
 if(r!==null){if(!r||typeof r.tenant_id!=='string'||r.tenant_id!==String(a?.tenant?.id??'')||typeof r.actor!=='string'||!r.actor||r.actor!==(a?.user??S.meta?.user??'')||typeof r.account_epoch!=='string'||!r.account_epoch)throw Error('响应不能绑定当前个人身份。');identity=JSON.stringify([typeof ACCESS==='undefined'?'':ACCESS.base,r.tenant_id,r.actor,r.account_epoch,v.c.key])}
 if(v.identity===identity)return;v.identity=identity;v.completedReceipt=null;v.notice=null;v.storageError='';if(!identity)return;
 try{const raw=experimentStorage().getItem(experimentStorageKey(identity));if(raw!==null){const saved=JSON.parse(raw);if(saved.schema!==1||saved.identity!==identity||!Array.isArray(saved.records))throw Error('invalid saved requests');for(const r of saved.records){if(!r||r.identity!==identity||typeof r.key!=='string'||!r.key.startsWith(identity+'\n')||!r.body||r.body.project!==v.c.key||typeof r.body.request_id!=='string'||!r.body.request_id||typeof r.body.action!=='string'||!r.body.action.startsWith('experiment_'))throw Error('invalid saved request');if(r.state==='recorded'&&!experimentValidReply(r.body,{receipt:r.receipt}))throw Error('invalid saved receipt');if(!EXPERIMENT_UI.requests.has(r.key))EXPERIMENT_UI.requests.set(r.key,{...r,state:r.state==='recorded'?'recorded':'unknown',busy:false});if(r.state==='recorded'){v.completedReceipt=r.receipt;v.notice={text:'已有已登记操作回执，可刷新视图；不会重新提交。',error:false}}}}}catch(error){v.storageError='无法核验已保存请求；请保留当前记录，不能另建意图。'}
}
async function learningExperimentsLoad(c){
 if(!learningCurrent(c)||!c.key)return;const v=experimentView(c),seq=++v.sequence;v.box.innerHTML='<p class="learning-muted">正在读取演练登记…</p>';
 try{const data=await get(learningPath(c.key,{experiments:'1'}));if(!experimentCurrent(v)||seq!==v.sequence)return;if(!Array.isArray(data.experiments)||!data.experiments.every(e=>experimentReadable(v,e)))throw Error('演练目录与当前项目不匹配。');experimentBindIdentity(v,data);v.data=data;v.selected=null;experimentPaint(v)}catch(error){if(experimentCurrent(v)&&seq===v.sequence)v.box.innerHTML='<p class="mem-notice error">'+h(error.message)+'</p>'}
}
async function learningExperimentOpen(c,id){
 if(!learningCurrent(c))return;const v=experimentView(c),seq=++v.sequence;v.box.innerHTML='<p class="learning-muted">正在读取固定实验合同…</p>';
 try{const data=await get(learningPath(c.key,{experiment:id}));if(!experimentCurrent(v)||seq!==v.sequence)return;if(!experimentReadable(v,data,id))throw Error('实验记录与当前项目或请求不匹配。');experimentBindIdentity(v,data);v.readError='';v.selected=data;if(v.completedReceipt?.experiment_id===id)v.notice={text:'操作已登记，当前记录已读取；不会重新提交。',error:false};experimentPaint(v)}catch(error){if(experimentCurrent(v)&&seq===v.sequence){v.readError=error.message;experimentPaint(v)}}
}
function experimentUnknown(v){return Array.from(EXPERIMENT_UI.requests.entries()).filter(([key,r])=>r.identity===v.identity&&r.state!=='recorded')}
function experimentStatus(s){return experimentStates[s]||'未知状态'}
function experimentNotice(v,text,error=false){if(!experimentCurrent(v))return;v.notice={text,error};const node=v.box.querySelector('#experimentNotice');if(node){node.textContent=text;node.className='mem-notice'+(error?' error':'')}}
function experimentValidReply(body,result){
 const r=result?.receipt;if(!r||typeof r.experiment_id!=='string'||!/^([0-9a-f]{32})$/.test(r.experiment_id)||typeof r.contract_hash!=='string'||!/^([0-9a-f]{64})$/.test(r.contract_hash)||r.request_id!==body.request_id||r.action!==body.action.slice('experiment_'.length)||typeof r.replayed!=='boolean'||typeof r.job_id!=='string'||(r.job_id!==''&&!/^[0-9a-f]{32}$/.test(r.job_id))||!['draft','sealed','running','cancelling','mechanism_passed','not_passed','cancelled','timed_out','stale','unknown'].includes(r.state))return false;
 if(body.experiment_id&&r.experiment_id!==body.experiment_id)return false;if(body.expected_hash&&r.contract_hash!==body.expected_hash)return false;return true;
}
async function experimentSend(v,body,retry=null){
 if(!experimentCurrent(v)||!v.identity||v.storageError)return;const pending=experimentUnknown(v);if(!retry&&pending.length){experimentNotice(v,'已有结果未知的请求；请先沿用原请求核对，不能修改意图另发。',true);return}
 const key=retry?.key??v.identity+'\n'+body.action+'\n'+(body.experiment_id||'create');let record=EXPERIMENT_UI.requests.get(key);
 if(retry){if(!record||record.identity!==v.identity||record.state!=='unknown'||record.body.request_id!==body.request_id)return}
 else if(!record||record.state==='recorded'){record={identity:v.identity,body:JSON.parse(JSON.stringify({...body,project:v.c.key,request_id:learningRequestId()})),state:'unknown'};EXPERIMENT_UI.requests.set(key,record)}
 if(record.busy)return;if(!experimentSave(v)){experimentPaint(v);return}record.busy=true;experimentPaint(v);experimentNotice(v,'正在提交；响应中断时保留原请求核对。');
 try{const result=await post('/api/learning',record.body);if(!experimentCurrent(v))return;if(!experimentValidReply(record.body,result))throw Error('没有收到与原请求匹配的完整回执，结果未知。');record.state='recorded';record.receipt=JSON.parse(JSON.stringify(result.receipt));if(!experimentSave(v)){record.state='unknown';throw Error(v.storageError)}v.completedReceipt=record.receipt;v.selected=null;v.readError='';experimentNotice(v,'操作已登记；正在读取本次记录，读取失败不会重新提交。');await learningExperimentOpen(v.c,record.receipt.experiment_id)}
 catch(error){if(!experimentCurrent(v))return;if(record.state==='recorded'){v.readError=error.message;experimentNotice(v,'操作已登记，视图待刷新；不会重新提交。',true)}else if(error.code==='experiment_not_written'){record.state='not_written';if(experimentSave(v)){EXPERIMENT_UI.requests.delete(key);experimentNotice(v,'服务器确认原请求未写入：'+error.message+' 可以核对输入后重新提交。',true)}else record.state='unknown'}else{record.state='unknown';experimentNotice(v,error.message+' 请用“按原请求核对”保留同一意图。',true)}}
 finally{record.busy=false;if(experimentCurrent(v))experimentPaint(v)}
}
function experimentSummary(e){const c=e.scientific_contract||{},b=e.budget||{};return `<div class="learning-statuses"><div><small>计划总数（分母不删减）</small><strong>${h(e.planned_slots??c.planned_slots??'未知')}</strong></div><div><small>已结算 / 仍预留</small><strong>${h(b.settled_calls??'未知')} / ${h(b.reserved_calls??'未知')}</strong></div><div><small>真实来源 / 合成来源族</small><strong>0 / ${h(c.synthetic_source_families??'未知')}</strong></div></div><p class="learning-muted">真实费用与 Token 未测量；合成计量单位：${h(b.synthetic_units??'未知')}。重复次数 ${h(c.repeats??'未知')} 不增加独立来源数。结果未知、失败与未执行槽仍计入完整计划。</p>`}
function experimentContract(c){return `<dl class="experiment-contract"><dt>候选 / 基线固定修订</dt><dd>${h(c.candidate_revision_id)} / ${h(c.baseline_revision_id||'无在用修订')}</dd><dt>来源项目与提交</dt><dd>${h(c.source?.project_id)} · ${h(c.source?.commit||'非 Git 来源，详见授权材料')}</dd><dt>材料保管 / 候选优化 / 结果选择</dt><dd>${h(c.roles?.curator)} / ${h(c.roles?.optimizer)} / ${h(c.roles?.selector)}</dd><dt>已知材料接触人</dt><dd>${h((c.known_custodians||[]).join('、'))}；不同角色名不证明独立未见。</dd><dt>冻结预算</dt><dd>${h(c.budget?.max_calls)} 次合成调用；总期限 ${h(c.budget?.timeout_seconds)} 秒；并发 ${h(c.budget?.concurrency)}</dd><dt>固定任务</dt><dd>${h(c.task_count)} 个任务，${h(c.repeats)} 次重复，基线与候选双臂；全部 ${h(c.planned_slots)} 个计划槽。</dd><dt>选择与停止规则</dt><dd>固定一个候选；基线封存当前真实检索结果。按重复、任务、基线 / 候选顺序执行；首次失败或未知结果停止后续槽。任务和答案为服务器登记的合成材料，不代表真实留出证据。</dd></dl><details><summary>完整科学合同摘要（不含受保护正文）</summary>${learningRaw(c)}</details>`}
function experimentPaint(v){
 if(!experimentCurrent(v))return;const e=v.selected,unknown=experimentUnknown(v),blocked=!v.identity||unknown.length>0||!!v.storageError;
 const recovery=unknown.map(([key,r],i)=>`<div class="mem-notice${r.busy?'':' error'}">${r.busy?'请求正在执行':'请求结果未知'}：${h(r.body.action)}。${r.busy?'':'仅可用同一身份和原意图核对。'}<details><summary>核对原操作与完整请求</summary>${learningRaw(r.body)}</details><button data-experiment-retry="${i}"${r.busy?' disabled':''}>按原请求核对</button></div>`).join('');
 v.box.innerHTML=`<div id="experimentNotice" class="mem-notice${v.storageError||v.notice?.error?' error':''}" role="status">${h(v.storageError||v.notice?.text||'')}</div>${v.readError?'<p class="mem-notice error">'+h((v.completedReceipt?'操作已登记，视图待刷新：':'读取失败：')+v.readError)+'</p>':''}${v.completedReceipt?'<button id="experimentReceiptRefresh">刷新已登记操作的视图</button>':''}${recovery}<p class="mem-hint">仅验证合成闭环机制；RSI 资格未开放，生产提示词等价性未确认，不自动采用知识。</p>`+(e?`<div class="mem-actions"><button id="experimentBack">返回演练目录</button><button id="experimentRefresh">刷新本次记录</button></div><h3>${h(experimentStatus(e.state))}</h3>${experimentSummary(e)}${experimentContract(e.scientific_contract||{})}<div class="mem-actions">${[['seal','封存本次合同'],['start','启动合成演练'],['cancel','停止本次演练']].map(([action,label])=>`<button data-experiment-action="${action}"${blocked||e.capabilities?.[action]!==true?' disabled':''}>${label}</button>`).join('')}</div><h3>全部计划槽</h3><div class="experiment-slots">${(e.slots||[]).map(s=>`<article class="mem-row"><strong>${h(s.ordinal)} · ${h(s.arm==='baseline'?'基线':'候选')} · 第 ${h(s.repeat)} 次</strong><p>${h(experimentStatus(s.state))} · 已结算 ${h(s.settled_calls)} · 预留 ${h(s.reserved_calls)}</p></article>`).join('')||'<p>尚未封存，计划总数仍在上方合同内保留。</p>'}</div><h3>材料与读取范围</h3><p class="learning-muted">${e.protected?'当前仅显示授权摘要；受保护材料未发送给本页。':'当前个人已获准读取以下完整材料。'}主动查看受保护材料会登记本人的接触记录，不会因此获得独立留出资格。</p><form id="experimentExpose"><div class="mem-fields">${(e.assets||[]).map((a,i)=>`<div class="mem-row"><label>${a.protected?`<input type="checkbox" data-experiment-asset="${i}"${blocked||e.capabilities?.expose!==true?' disabled':''}>`:''}${h(a.kind)} · ${h(a.family||a.id)}</label>${a.protected?'<p class="learning-muted">正文受保护</p>':`<details><summary>完整材料</summary>${learningRaw(a.content)}</details>`}</div>`).join('')}</div><button${blocked||e.capabilities?.expose!==true?' disabled':''}>登记本人查看所选材料</button></form>${e.protected?'':`<details><summary>完整已登记报告与原始记录</summary>${learningRaw(e)}</details>`}`:`<div class="mem-actions"><button id="experimentReload">刷新演练目录</button></div><div>${(v.data?.experiments||[]).map((x,i)=>`<article class="mem-row"><h3>${h(experimentStatus(x.state))}</h3>${experimentSummary(x)}<button data-experiment-open="${i}">查看固定合同与记录</button></article>`).join('')||'<p class="learning-muted">还没有演练登记。</p>'}</div><details><summary>登记新的合成演练</summary><p class="learning-muted">先在经验目录固定候选修订。三个角色必须是当前项目的真实成员；浏览不会自动创建或执行。</p><form id="experimentCreate"><div class="mem-fields"><label>候选修订编号<input id="experimentRevision" required></label>${[['Curator','材料保管人'],['Optimizer','候选优化人'],['Selector','结果选择人']].map(([id,label])=>`<label>${label}<input id="experiment${id}" required></label>`).join('')}<label>每个任务的重复次数<input id="experimentRepeats" type="number" min="1" max="10" value="1" required></label><label>整轮总时限（秒）<input id="experimentTimeout" type="number" min="1" max="3600" value="120" required></label></div><p class="learning-muted">计划为 3 个合成来源族 × 双臂 × 重复次数。调用上限随计划固定，重试不增加预算。</p><button${blocked||v.data?.can_create!==true?' disabled':''}>保存演练草稿</button></form></details>`);
 if(v.completedReceipt)v.box.querySelector('#experimentReceiptRefresh').onclick=()=>learningExperimentOpen(v.c,v.completedReceipt.experiment_id);
 v.box.querySelectorAll('[data-experiment-retry]').forEach(b=>b.onclick=()=>{const [key,r]=unknown[Number(b.dataset.experimentRetry)];return experimentSend(v,r.body,{key})});
 if(e){v.box.querySelector('#experimentBack').onclick=()=>learningExperimentsLoad(v.c);v.box.querySelector('#experimentRefresh').onclick=()=>learningExperimentOpen(v.c,e.id);v.box.querySelectorAll('[data-experiment-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.experimentAction;if(b.disabled)return;const body={action:'experiment_'+action,experiment_id:e.id};if(action==='seal')body.expected_hash=e.contract_hash;return experimentSend(v,body)});v.box.querySelector('#experimentExpose').onsubmit=event=>{event.preventDefault();if(blocked||e.capabilities?.expose!==true)return;const assets=Array.from(v.box.querySelectorAll('[data-experiment-asset]')).filter(n=>n.checked).map(n=>e.assets[Number(n.dataset.experimentAsset)].id);if(!assets.length)return experimentNotice(v,'请选择本人确需查看的材料。',true);return experimentSend(v,{action:'experiment_expose',experiment_id:e.id,asset_ids:assets,expected_hash:e.contract_hash})}}
 else{v.box.querySelector('#experimentReload').onclick=()=>learningExperimentsLoad(v.c);v.box.querySelectorAll('[data-experiment-open]').forEach(b=>b.onclick=()=>learningExperimentOpen(v.c,v.data.experiments[Number(b.dataset.experimentOpen)].id));v.box.querySelector('#experimentCreate').onsubmit=event=>{event.preventDefault();if(blocked||v.data?.can_create!==true)return;try{const repeats=learningInteger(v.box.querySelector('#experimentRepeats').value,1,10,'重复次数'),contract={candidate_revision_id:v.box.querySelector('#experimentRevision').value,repeats,max_calls:6*repeats,timeout_seconds:learningInteger(v.box.querySelector('#experimentTimeout').value,1,3600,'总时限'),curator:v.box.querySelector('#experimentCurator').value,optimizer:v.box.querySelector('#experimentOptimizer').value,selector:v.box.querySelector('#experimentSelector').value,executor_id:'synthetic-fixed-a-v1',task_set:'synthetic-three-families-v1'};if(!contract.candidate_revision_id.trim())throw Error('请填写已固定的完整候选修订编号。');if(!['curator','optimizer','selector'].every(k=>typeof contract[k]==='string'&&contract[k].trim()))throw Error('请填写三个角色的真实成员账号。');return experimentSend(v,{action:'experiment_create',contract})}catch(error){experimentNotice(v,error.message,true)}}}
}
function learningManagedJob(job,index){return `<article class="learning-job" data-learning-job="${index}"><h3>合成机制演练记录</h3><p class="learning-muted">${h(learningState(job.status))}。仅为已登记状态，未核验当前有效性；不能当作人工采用依据。</p><p>${job.protected?'实验材料受保护，未返回正文。':'当前个人可查看完整已登记材料。'}</p>${job.protected?'':`<details><summary>完整已登记记录</summary>${learningRaw(job)}</details>`}${(job.experiment_ids||[]).map(id=>`<button data-learning-experiment-open="${h(id)}">打开演练与全部计划</button>`).join('')}</article>`}
function learningManagedRevision(c,d){const r=d.data.revision||{},ids=Array.from(new Set([r,...(d.data.history||[]),...(d.data.jobs||[])].flatMap(x=>x.experiment_ids||[])));d.root.innerHTML=`<section class="mem-card"><h2>${r.managed?'受管实验修订':'含受管材料的历史记录'}</h2><p class="mem-hint">${r.managed?'此修订已用于合成机制演练，不能从原手工入口启动、修订或采用。':'同一知识条目的历史中含受管材料；本页只读已登记记录，未核验当前来源。'}旧手工任务的完整历史仍按原记录保留。</p>${r.protected?'<p>当前个人未获准读取受保护的完整材料。</p>':`<details><summary>完整修订记录</summary>${learningRaw(r)}</details>`}<details><summary>完整历史修订（按当前读取范围）</summary>${learningRaw(d.data.history||[])}</details><details><summary>完整已登记决定（按当前读取范围）</summary>${learningRaw(d.data.decisions||[])}</details><div id="learningDetailJobs"></div>${ids.map(id=>`<button data-learning-experiment-open="${h(id)}">查看演练合同</button>`).join('')}</section>`;learningPaintJobs(c,d.data.jobs||[],d.root.querySelector('#learningDetailJobs'),d);d.root.querySelectorAll('[data-learning-experiment-open]').forEach(b=>b.onclick=()=>learningExperimentOpen(c,b.dataset.learningExperimentOpen))}
"""

LEARNING_CSS += r"""
#learningExperiments{margin-top:20px}.experiment-contract{display:grid;grid-template-columns:minmax(160px,.5fr) minmax(0,1fr);gap:12px 20px;font-size:14px;line-height:1.8}.experiment-contract dt{color:var(--mut)}.experiment-contract dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.experiment-slots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#learningExperiments button{min-height:40px}#learningExperiments .mem-row{min-width:0;overflow-wrap:anywhere}@media(max-width:760px){.experiment-contract,.experiment-slots{grid-template-columns:minmax(0,1fr)}.experiment-contract{gap:4px}.experiment-contract dd{margin-bottom:12px}#learningExperiments button{min-height:44px}}
"""
